func autoMigrateSchematic(ctx context.Context, old v13.Schematic) (Schematic, error) {
	nodes, err := lo.MapErr(old.Nodes, func(v v13.Node, _ int) (Node, error) {
		return MigrateNode(ctx, v)
	})
	if err != nil {
		return Schematic{}, err
	}
	return Schematic{
		Key:     old.Key,
		Name:    old.Name,
		Nodes:   nodes,
		Edges:   old.Edges,
		Group:   old.Group,
		Project: old.Project,
	}, nil
}

